3	import { useState, useTransition } from "react";
4	import { submitFeedback } from "@/lib/actions-feedback";
5	import { useConsentPending } from "@/components/useConsentPending";
6	
7	type Kind = "BUG" | "FEATURE";
8	
9	/**
10	 * Shared bug/feature form. Captures the current path as `url` on submit and
11	 * calls the `submitFeedback` server action. Shows a thank-you state when done.
12	 * Reused by the floating widget and the dashboard feedback page.
13	 */
14	export function FeedbackForm({
15	  onDone,
16	  compact,
17	}: {
18	  onDone?: () => void;
19	  compact?: boolean;
20	}) {
21	  const [kind, setKind] = useState<Kind>("BUG");
22	  const [title, setTitle] = useState("");
23	  const [body, setBody] = useState("");
24	  const [error, setError] = useState<string | null>(null);
25	  const [done, setDone] = useState(false);
26	  const [pending, start] = useTransition();
27	
28	  function reset() {
29	    setKind("BUG");
30	    setTitle("");
31	    setBody("");
32	    setError(null);
33	    setDone(false);
34	  }
35	
36	  function handleSubmit(e: React.FormEvent) {
37	    e.preventDefault();
38	    setError(null);
39	    const url = typeof window !== "undefined" ? window.location.pathname : "";
40	    start(async () => {
41	      const res = await submitFeedback(kind, title, body, url);
42	      if (res?.error) {
43	        setError(res.error);
44	        return;
45	      }
46	      setDone(true);
47	    });
48	  }
49	
50	  if (done) {
51	    return (
52	      <div className="flex flex-col items-center justify-center gap-3 py-8 text-center">
53	        <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-3">
54	          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="#34d399" strokeWidth="2">
55	            <path d="M20 6 9 17l-5-5" />
56	          </svg>
57	        </div>
58	        <h3 className="text-base font-semibold">Thanks for the feedback!</h3>
59	        <p className="max-w-xs text-sm text-slate-400">
60	          We&apos;ve logged your {kind === "BUG" ? "bug report" : "feature request"} and the team will take a look.
61	        </p>
62	        <div className="flex gap-2">
63	          <button className="btn-secondary" onClick={reset}>
64	            Send another
65	          </button>
66	          {onDone && (
67	            <button className="btn-primary" onClick={onDone}>
68	              Done
69	            </button>
70	          )}
71	        </div>
72	      </div>
73	    );
74	  }
75	
76	  return (
77	    <form onSubmit={handleSubmit} className="space-y-4">
78	      {error && (
79	        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-400">
80	          {error}
81	        </div>
82	      )}
83	
84	      <div className="grid grid-cols-2 gap-2">
85	        <button
86	          type="button"
87	          onClick={() => setKind("BUG")}
88	          className={
89	            kind === "BUG"
90	              ? "btn-primary justify-center"
91	              : "btn-secondary justify-center"
92	          }
93	        >
94	          🐞 Report a bug
95	        </button>
96	        <button
97	          type="button"
98	          onClick={() => setKind("FEATURE")}
99	          className={
100	            kind === "FEATURE"
101	              ? "btn-primary justify-center"
102	              : "btn-secondary justify-center"
103	          }
104	        >
105	          ✨ Request a feature
106	        </button>
107	      </div>
108	
109	      <div>
110	        <label className="label">Title</label>
111	        <input
112	          className="input"
113	          value={title}
114	          onChange={(e) => setTitle(e.target.value)}
115	          placeholder={kind === "BUG" ? "What went wrong?" : "What would you like to see?"}
116	          minLength={3}
117	          maxLength={150}
118	          required
119	        />
120	      </div>
121	
122	      <div>
123	        <label className="label">Description</label>
124	        <textarea
125	          className={`input resize-y ${compact ? "min-h-24" : "min-h-32"}`}
126	          value={body}
127	          onChange={(e) => setBody(e.target.value)}
128	          placeholder={
129	            kind === "BUG"
130	              ? "Steps to reproduce, what you expected, and what actually happened."
131	              : "Describe the feature and how it would help you."
132	          }
133	          minLength={5}
134	          maxLength={5000}
135	          required
136	        />
137	      </div>
138	
139	      <div className="flex items-center justify-end gap-3">
140	        {onDone && (
141	          <button type="button" className="btn-ghost" onClick={onDone} disabled={pending}>
142	            Cancel
143	          </button>
144	        )}
145	        <button className="btn-primary px-6" disabled={pending}>
146	          {pending ? "Sending…" : "Submit"}
147	        </button>
148	      </div>
149	    </form>
150	  );
151	}
