153	/**
154	 * Floating "Feedback" button (bottom-right) that opens a modal with the shared
155	 * form. Self-contained; mounted globally by the portal Shell for both portals.
156	 */
157	export default function FeedbackWidget() {
158	  const [open, setOpen] = useState(false);
159	  const consentPending = useConsentPending();
160	
161	  return (
162	    <>
163	      <button
164	        onClick={() => setOpen(true)}
165	        aria-label="Send feedback"
166	        /*
167	          z-40 put this UNDER the cookie banner entirely, and the banner's
168	          full-width wrapper swallowed the click even where nothing was drawn.
169	          The wrapper no longer takes pointer events, and this steps up out of the
170	          banner's footprint on small screens until the visitor has chosen.
171	        */
172	        className={`fixed bottom-4 right-20 z-40 inline-flex items-center gap-2 rounded-full border border-white/10 bg-gradient-to-br from-accent-blue to-brand-500 px-4 py-2.5 text-sm font-semibold text-white shadow-lg shadow-brand-500/30 transition hover:brightness-110 ${
173	          consentPending ? "max-sm:mb-52" : ""
174	        }`}
175	      >
176	        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
177	          <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
178	        </svg>
179	        Feedback
180	      </button>
181	
182	      {open && (
183	        <div
184	          className="fixed inset-0 z-50 flex items-end justify-center bg-black/60 p-4 backdrop-blur-sm sm:items-center"
185	          onClick={() => setOpen(false)}
186	        >
187	          <div
188	            className="card w-full max-w-md animate-fade-up"
189	            onClick={(e) => e.stopPropagation()}
190	          >
191	            <div className="mb-4 flex items-start justify-between">
192	              <div>
193	                <h2 className="text-lg font-semibold">Send feedback</h2>
194	                <p className="mt-0.5 text-sm text-slate-400">
195	                  Spotted a bug or have an idea? Let us know.
196	                </p>
197	              </div>
198	              <button
199	                className="btn-ghost -mr-2 -mt-1 px-2"
200	                aria-label="Close"
201	                onClick={() => setOpen(false)}
202	              >
203	                ✕
204	              </button>
205	            </div>
206	            <FeedbackForm onDone={() => setOpen(false)} />
207	          </div>
208	        </div>
209	      )}
210	    </>
211	  );
212	}
