3	import {
4	  useCallback,
5	  useEffect,
6	  useRef,
7	  useState,
8	  type ClipboardEvent,
9	  type ReactNode,
10	} from "react";
11	import { SUPPORT_REPLY_WITHIN } from "@/lib/support-promise";
12	import { useConsentPending } from "@/components/useConsentPending";
13	
14	/** The signed-in viewer, if any — passed from the server layout so the widget
15	 *  can prefill (and not re-ask for) name + email, and require them otherwise. */
16	export type ChatViewer = { name: string | null; email: string | null } | null;
17	
18	const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
19	
20	/** Render bot/agent text with clickable links — markdown [label](url) and bare
21	 *  URLs (absolute or site-relative). Internal links open in place; external in a
22	 *  new tab. Everything else is plain text (the container keeps line breaks). */
23	function renderRich(text: string): ReactNode[] {
24	  const out: ReactNode[] = [];
25	  const re = /\[([^\]]+)\]\((https?:\/\/[^\s)]+|\/[^\s)]+)\)|(https?:\/\/[^\s]+|\/[a-z0-9][^\s]*)/gi;
26	  let last = 0;
27	  let key = 0;
28	  let m: RegExpExecArray | null;
29	  while ((m = re.exec(text)) !== null) {
30	    if (m.index > last) out.push(text.slice(last, m.index));
31	    const label = m[1] ?? m[3];
32	    const href = m[2] ?? m[3];
33	    const external = /^https?:\/\//i.test(href);
34	    out.push(
35	      <a
36	        key={`l${key++}`}
37	        href={href}
38	        {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
39	        className="font-medium text-brand-300 underline underline-offset-2 hover:text-brand-200"
40	      >
41	        {label}
42	      </a>,
43	    );
44	    last = re.lastIndex;
45	  }
46	  if (last < text.length) out.push(text.slice(last));
47	  return out;
48	}
