50	/**
51	 * First-party live-chat widget (Tidio-style). Floating bubble bottom-right that
52	 * opens a chat panel. Identifies the visitor with a persistent `visitorId` in
53	 * localStorage, posts messages to /api/chat, and polls GET /api/chat every ~4s
54	 * while open. On the very first message it optionally captures name + email.
55	 *
56	 * Mounted by the orchestrator (near <CookieConsent/> in app/layout.tsx) — it
57	 * does not mount itself anywhere.
58	 */
59	
60	type Attachment = { id: string; mime: string; sizeBytes: number };
61	type PlanCardData = {
62	  key: string;
63	  product: string;
64	  name: string;
65	  badge?: string;
