98	        <span className="text-xs text-slate-400">{c.period}</span>
99	        {c.oldPriceLabel && <span className="text-xs text-slate-500 line-through">{c.oldPriceLabel}</span>}
100	      </div>
101	      <ul className="mt-2 space-y-1">
102	        {c.features.map((f, i) => (
103	          <li key={i} className="flex items-start gap-1.5 text-xs text-slate-300">
104	            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="mt-0.5 shrink-0 text-emerald-400" aria-hidden>
105	              <path d="M20 6 9 17l-5-5" />
106	            </svg>
107	            <span>{f}</span>
108	          </li>
109	        ))}
110	      </ul>
111	      <a
112	        href={c.ctaUrl}
113	        {...(external ? { target: "_blank", rel: "noopener noreferrer" } : {})}
114	        className="mt-3 flex w-full items-center justify-center gap-1.5 rounded-xl bg-gradient-to-br from-brand-500 to-accent-blue px-3 py-2 text-sm font-semibold text-white transition hover:opacity-90"
115	      >
116	        {c.ctaLabel}
117	        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6" /></svg>
118	      </a>
119	    </div>
120	  );
