123	const VISITOR_KEY = "nxeon_chat_visitor";
124	// The active conversation lives in sessionStorage so a NEW browser session
125	// (coming back later) starts a fresh chat, while past threads stay resumable
126	// from the history list.
127	const ACTIVE_KEY = "nxeon_chat_active";
128	const POLL_MS = 4000;
129	
130	type ConvoSummary = {
131	  id: string;
132	  title: string;
133	  preview: string;
134	  unread: boolean;
135	  status: string;
136	  lastMessageAt: string;
