import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ results: [] }, { status: 401, headers: NO_STORE_HEADERS });
  }
  const q = (req.nextUrl.searchParams.get("q") ?? "").trim();
  if (q.length < 2) return NextResponse.json({ results: [] }, { headers: NO_STORE_HEADERS });

  const isAdmin = user.role === "ADMIN";
  const results: { type: string; label: string; sub?: string; href: string }[] = [];

  const servers = await db.server.findMany({
    where: {
      hostname: { contains: q, mode: "insensitive" },
      ...(isAdmin ? {} : { userId: user.id }),
    },
    include: { user: true },
    take: 6,
  });
  for (const s of servers) {
    results.push({
      type: "server",
      label: s.hostname,
      sub: isAdmin ? `${s.user.email} · ${s.status.toLowerCase()}` : s.status.toLowerCase(),
      href: `/dashboard/servers/${s.id}`,
    });
  }

  const domains = await db.domain.findMany({
    where: { name: { contains: q, mode: "insensitive" }, ...(isAdmin ? {} : { userId: user.id }) },
    take: 4,
  });
  for (const d of domains) {
    results.push({ type: "domain", label: d.name, sub: d.status.toLowerCase(), href: `/dashboard/domains/${d.id}` });
  }

  const tickets = await db.ticket.findMany({
    where: { subject: { contains: q, mode: "insensitive" }, ...(isAdmin ? {} : { userId: user.id }) },
    take: 4,
  });
  for (const t of tickets) {
    results.push({
      type: "ticket",
      label: t.subject,
      sub: t.status.toLowerCase(),
      href: isAdmin ? `/admin/support/${t.id}` : `/dashboard/support/${t.id}`,
    });
  }

  if (isAdmin) {
    const users = await db.user.findMany({
      where: {
        OR: [
          { email: { contains: q, mode: "insensitive" } },
          { name: { contains: q, mode: "insensitive" } },
        ],
      },
      take: 5,
    });
    for (const u of users) {
      results.push({ type: "customer", label: u.name, sub: u.email, href: `/admin/users/${u.id}` });
    }
  }

  // Results are scoped to the caller — for an admin they include other
  // customers' hostnames, emails and ticket subjects. `?q=` is a plain GET, so
  // without this a shared cache keyed on the URL would happily replay an
  // admin's result set to whoever searched the same term next.
  return NextResponse.json({ results: results.slice(0, 15) }, { headers: NO_STORE_HEADERS });
}
