import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { listFolders } from "@/lib/actions-mail";

export const dynamic = "force-dynamic";

// Lightweight unread-INBOX count for the sidebar "Inbox" badge. Polled from the
// client (Shell), never from the server layout render — IMAP is far too slow to
// sit in the critical path of every dashboard page. Fails SOFT to 0 so a mailbox
// hiccup (no mailbox, IMAP down) never breaks the nav or leaks an error.
export async function GET() {
  const user = await currentUser();
  if (!user) return NextResponse.json({ unread: 0 }, { status: 401 });
  try {
    const folders = await listFolders();
    const inbox = folders.find((f) => f.role === "inbox");
    return NextResponse.json({ unread: inbox?.unread ?? 0 }, { headers: { "cache-control": "no-store" } });
  } catch {
    return NextResponse.json({ unread: 0 }, { headers: { "cache-control": "no-store" } });
  }
}
