import { NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { db } from "@/lib/db";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * READ-ONLY support-attention counts for the admin floating support indicator.
 *
 * GET /api/admin/support-unread → { tickets, chat } —
 *   - `tickets`: tickets awaiting a staff reply (OPEN + CUSTOMER_REPLY), the same
 *     signal as the "Awaiting staff" stat on /admin/support and the sidebar badge.
 *   - `chat`: live-chat conversations flagged `unreadForAgent` (mirrors the
 *     existing /api/admin/chat-unread source and the chat inbox badge).
 *
 * <AdminIndicators/> polls this while an admin tab is open and animates the
 * bubble (bell shake + pulse) when the combined count increases. Gated to
 * support staff exactly like the inbox; never writes anything, and each count
 * fails soft to 0 so a transient DB hiccup can't surface as a widget error.
 */
export async function GET() {
  const user = await realUser();
  if (!user || !canAccess(user.role, "support")) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  const [tickets, chat] = await Promise.all([
    db.ticket
      .count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
      .catch(() => 0),
    db.chatConversation.count({ where: { unreadForAgent: true } }).catch(() => 0),
  ]);

  return NextResponse.json({ tickets, chat }, { headers: NO_STORE_HEADERS });
}

