import { NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { listFolders } from "@/lib/actions-mail";
import { listCompanyMailboxes } from "@/lib/actions-company-mail";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * READ-ONLY unread-mail count for the admin floating email indicator.
 *
 * GET /api/admin/inbox-unread → { unread } — the combined unread INBOX count
 * across every company mailbox (admin@, support@, …). Mirrors the customer
 * /api/mail/unread route: IMAP is far too slow to sit in a server layout render,
 * so <AdminIndicators/> polls this from the browser and animates the bubble when
 * the count increases.
 *
 * Gated to the "platform" area (same as the /admin/inbox page). Fails SOFT to 0
 * per mailbox and overall so a mailbox hiccup / IMAP outage never surfaces as a
 * widget error. Never writes anything.
 */
export async function GET() {
  const user = await realUser();
  if (!user || !canAccess(user.role, "platform")) {
    return NextResponse.json({ unread: 0 }, { status: 401, headers: NO_STORE_HEADERS });
  }

  try {
    const boxes = await listCompanyMailboxes();
    // Cap the fan-out: each mailbox is one IMAP connection. A handful of company
    // mailboxes is the norm; never open more than a few per poll.
    const targets = boxes.slice(0, 6);
    const counts = await Promise.all(
      targets.map(async (b) => {
        try {
          const folders = await listFolders(b.address);
          const inbox = folders.find((f) => f.role === "inbox");
          return inbox?.unread ?? 0;
        } catch {
          return 0; // this mailbox failed — count it as 0, don't fail the whole poll
        }
      }),
    );
    const unread = counts.reduce((sum, n) => sum + n, 0);
    return NextResponse.json({ unread }, { headers: NO_STORE_HEADERS });
  } catch {
    return NextResponse.json({ unread: 0 }, { headers: NO_STORE_HEADERS });
  }
}

