"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";

/**
 * Admin-portal floating attention indicators (bottom-right), the ops-portal
 * replacement for the customer Feedback + live-chat bubbles (which are suppressed
 * on /admin — see components/ChatWidget.tsx and the Shell's FeedbackWidget gate).
 *
 * Two bubbles:
 *   • Support — tickets awaiting a staff reply + unread live-chat conversations
 *     (GET /api/admin/support-unread). Jumps to /admin/support.
 *   • Email — unread across the company mailboxes (GET /api/admin/inbox-unread).
 *     Jumps to /admin/inbox.
 *
 * Each shows a bell/badge and, when its count INCREASES beyond the last seen
 * value, shakes the bell and pulses a ring so a newly-arrived ticket, chat reply
 * or email is impossible to miss. Everything is best-effort and read-only: a
 * failed poll simply skips a tick, and the first load never animates for items
 * that were already waiting.
 */

const POLL_MS = 15_000;

type IndicatorProps = {
  href: string;
  title: string;
  count: number;
  /** Bumped by the parent each time `count` rises, to (re)trigger the shake. */
  alertKey: number;
  icon: React.ReactNode;
};

function Indicator({ href, title, count, alertKey, icon }: IndicatorProps) {
  const has = count > 0;
  return (
    <Link
      href={href}
      title={count > 0 ? `${title} — ${count} waiting` : title}
      aria-label={count > 0 ? `${title}, ${count} waiting` : title}
      className="group relative flex h-12 w-12 items-center justify-center rounded-full border border-white/10 bg-gradient-to-br from-brand-500 to-accent-blue text-white shadow-xl transition hover:scale-105"
    >
      {/* Pulsing ring while anything is waiting. */}
      {has && (
        <span
          className="pointer-events-none absolute inset-0 rounded-full bg-brand-500/60 motion-safe:animate-ping"
          aria-hidden
        />
      )}
      {/* The bell/icon re-shakes whenever alertKey changes (a new arrival). */}
      <span
        key={alertKey}
        className={has ? "relative motion-safe:animate-bell-shake" : "relative"}
      >
        {icon}
      </span>
      {count > 0 && (
        <span className="absolute -right-1 -top-1 flex h-5 min-w-[20px] items-center justify-center rounded-full border-2 border-navy-950 bg-red-500 px-1 text-[10px] font-bold text-white">
          {count > 99 ? "99+" : count}
        </span>
      )}
    </Link>
  );
}

/** Poll `url` for a numeric total; return the running total + an alert key that
 *  increments every time the total rises (so the icon can re-trigger its shake). */
function useAttention(url: string, extract: (data: unknown) => number) {
  const [count, setCount] = useState(0);
  const [alertKey, setAlertKey] = useState(0);
  // `null` until the first successful poll, so a first load never animates for
  // items already waiting.
  const last = useRef<number | null>(null);

  useEffect(() => {
    let stopped = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    async function poll() {
      try {
        const res = await fetch(url, { cache: "no-store" });
        if (res.ok) {
          const data = (await res.json().catch(() => null)) as unknown;
          const n = extract(data);
          setCount(n);
          if (last.current !== null && n > last.current) {
            setAlertKey((k) => k + 1); // rose since last poll → shake
          }
          last.current = n;
        }
      } catch {
        /* transient error — skip this tick */
      } finally {
        if (!stopped) timer = setTimeout(poll, POLL_MS);
      }
    }

    poll();
    return () => {
      stopped = true;
      if (timer) clearTimeout(timer);
    };
    // extract is a stable inline fn per call site; url is constant.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [url]);

  return { count, alertKey };
}

export default function AdminIndicators() {
  const support = useAttention("/api/admin/support-unread", (d) => {
    const o = (d ?? {}) as { tickets?: number; chat?: number };
    return (Number(o.tickets) || 0) + (Number(o.chat) || 0);
  });
  const email = useAttention("/api/admin/inbox-unread", (d) => {
    const o = (d ?? {}) as { unread?: number };
    return Number(o.unread) || 0;
  });

  return (
    <div className="fixed bottom-4 right-4 z-[60] flex flex-col items-end gap-3">
      <Indicator
        href="/admin/support"
        title="Support & live chat"
        count={support.count}
